package com.celik.kingdoms;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.celik.kingdoms.ArtifactRules.*;
import com.celik.kingdoms.ArtifactRules.Record;
class ArtifactRulesTest {
 @Test void fourteenTypesAndGuaranteedEligibleTriggers(){var c=new ArtifactConfig();c.validate();assertEquals(14,c.types.size());assertEquals(ArtifactConfig.KEYS,c.types.keySet());assertTrue(c.types.values().stream().flatMap(t->t.variants.stream()).allMatch(v->v.chance==1));assertEquals(3,c.upgradeIngots);}
 @Test void specifiedDurabilityAndUpgradeValues(){var c=new ArtifactConfig();assertEquals(512,c.types.get("thunder_axe").maxUses);assertEquals(768,c.types.get("thunder_axe").upgradedMaxUses);assertEquals(1000,c.types.get("void_scythe").maxUses);assertEquals(100,c.types.get("guardian_angel").maxUses);assertFalse(c.types.get("guardian_angel").netheriteUpgradeable);assertEquals(.25,c.types.get("vampire_sword").variants.getFirst().value);assertEquals(.5,c.types.get("vampire_sword").upgradedValue);assertEquals(1.5,c.types.get("frostbite_sword").upgradedDurationSeconds);}
 @Test void nativeItemDurabilityIsSelectedByZero(){var c=new ArtifactConfig();for(String key:List.of("multi_pickaxe","vampire_sword","frostbite_sword","thorns_shield","wind_burst_spear"))assertEquals(0,c.types.get(key).maxUses);}
 @Test void phaseProbabilitiesFollowRealAge(){var c=new ArtifactConfig();assertEquals(.001,c.chance(1));assertEquals(.001,c.chance(2));assertEquals(.0015,c.chance(3));assertEquals(.002,c.chance(6));assertEquals(.003,c.chance(7));assertEquals(.003,c.chance(100));}
 @Test void offlineAndReservedRecordsCannotLimitSpawning(){var c=new ArtifactConfig();var d=new Data();for(String key:c.types.keySet())for(int i=0;i<150;i++){var r=generate(key,c.types.get(key),new Random(i));d.records.put(r.id,r);}Set<String> expected=new HashSet<>(c.types.keySet());expected.remove("golden_crown");assertEquals(expected,new HashSet<>(eligible(c,d,7)));}
 @Test void crownNeverEntersTheDropPool(){var c=new ArtifactConfig();assertFalse(eligible(c,new Data(),Long.MAX_VALUE).contains("golden_crown"));c.types.get("golden_crown").airDropEligible=true;assertFalse(eligible(c,new Data(),Long.MAX_VALUE).contains("golden_crown"));assertThrows(IllegalArgumentException.class,c::validate);}
 @Test void expandedCatalogAddsOnlyMissingTypesAndPreservesOldBalance(){var c=new ArtifactConfig();c.types.get("vampire_sword").enabled=false;c.chanceByDay.put(1,.13);var tree=com.google.gson.JsonParser.parseString(Store.JSON.toJson(c)).getAsJsonObject();tree.remove("expandedCatalogVersion");for(String key:ArtifactConfig.ADDITIONAL_KEYS)tree.getAsJsonObject("types").remove(key);var loaded=Store.JSON.fromJson(tree,ArtifactConfig.class);loaded.validate();assertEquals(14,loaded.types.size());assertFalse(loaded.types.get("vampire_sword").enabled);assertEquals(.13,loaded.chance(1));loaded.types.get("advanced_axe").enabled=false;assertFalse(Store.JSON.fromJson(Store.JSON.toJson(loaded),ArtifactConfig.class).types.get("advanced_axe").enabled);}
 @Test void disabledAndLockedTypesNeverSelected(){var c=new ArtifactConfig();c.types.get("thunder_axe").minDay=7;c.types.get("guardian_angel").enabled=false;assertFalse(eligible(c,new Data(),6).contains("thunder_axe"));assertTrue(eligible(c,new Data(),7).contains("thunder_axe"));assertFalse(eligible(c,new Data(),7).contains("guardian_angel"));}
 @Test void generatedSnapshotsAndIdentities(){var c=new ArtifactConfig();for(String k:c.types.keySet()){var a=generate(k,c.types.get(k),new Random(4));var b=generate(k,c.types.get(k),new Random(4));assertNotEquals(a.id,b.id);assertNotEquals(a.nonce,b.nonce);assertEquals(a.chance,b.chance);assertEquals(c.types.get(k).upgradedValue,a.upgradedValue);}}
 @Test void guardianCanSpendItsFinalCharge(){var c=new ArtifactConfig();var r=generate("guardian_angel",c.types.get("guardian_angel"),new Random(1));r.uses=1;assertTrue(consume(r,1000));assertEquals(0,r.uses);assertFalse(consume(r,2000));assertFalse(active(r,2000));}
 @Test void toolsDoNotSpendLedgerCharges(){var c=new ArtifactConfig();var r=generate("void_scythe",c.types.get("void_scythe"),new Random(1));assertFalse(consume(r,1000));assertEquals(1000,r.uses);assertTrue(active(r,1000));}
 @Test void guardianRepairRoundsUpAndClamps(){var c=new ArtifactConfig();var r=generate("guardian_angel",c.types.get("guardian_angel"),new Random(1));r.uses=0;assertEquals(25,repairedUses(r,.25));r.uses=99;assertEquals(100,repairedUses(r,.25));}
 @Test void corruptIdentityRejected(){var d=new Data();var r=generate("vampire_sword",new ArtifactConfig().types.get("vampire_sword"),new Random());d.records.put(r.id,r);validate(d);r.nonce=null;assertThrows(IllegalStateException.class,()->validate(d));}
 @Test void invalidProbabilitiesAndBalanceRejected(){var c=new ArtifactConfig();c.chanceByDay.put(1,1.01);assertThrows(IllegalArgumentException.class,c::validate);var n=new ArtifactConfig();n.repairFraction=0;assertThrows(IllegalArgumentException.class,n::validate);var b=new ArtifactConfig();b.types.get("vampire_sword").variants.getFirst().chance=1.01;assertThrows(IllegalArgumentException.class,b::validate);}
 @Test void retiredIdentitiesRemainInvalidAfterSerialization(){var c=new ArtifactConfig();var d=new Data();var r=generate("vampire_sword",c.types.get("vampire_sword"),new Random());r.retired=true;d.records.put(r.id,r);var loaded=Store.JSON.fromJson(Store.JSON.toJson(d),Data.class);assertTrue(loaded.records.get(r.id).retired);assertFalse(active(loaded.records.get(r.id),1000));}
 @Test void legacyConfigReplacesCatalogPreservingDropOdds(){var json=com.google.gson.JsonParser.parseString(Store.JSON.toJson(new ArtifactConfig())).getAsJsonObject();json.addProperty("abilityBalanceVersion",1);json.addProperty("globalCap",12);json.getAsJsonObject("types").add("smelter_pickaxe",json.getAsJsonObject("types").get("multi_pickaxe"));var loaded=Store.JSON.fromJson(json,ArtifactConfig.class);loaded.validate();assertEquals(ArtifactConfig.KEYS,loaded.types.keySet());assertEquals(.001,loaded.chance(1));assertFalse(Store.JSON.toJson(loaded).contains("globalCap"));}
 @Test void currentAdminCustomizationsSurviveReload(){var c=new ArtifactConfig();c.types.get("vampire_sword").variants.getFirst().chance=.2;var loaded=Store.JSON.fromJson(Store.JSON.toJson(c),ArtifactConfig.class);loaded.validate();assertEquals(.2,loaded.types.get("vampire_sword").variants.getFirst().chance);}
 @Test void oldSharedIdentityMigratesKeepingDamageFraction(){var c=new ArtifactConfig();var r=generate("thunder_axe",c.types.get("thunder_axe"),new Random(1));r.owner=UUID.randomUUID();r.uses=100;r.maxUses=500;r.readyAt=9000;r.upgraded=true;r.revision=7;var json=com.google.gson.JsonParser.parseString(Store.JSON.toJson(r)).getAsJsonObject();json.addProperty("abilityBalanceVersion",1);json.addProperty("chance",.5);Record loaded=Store.JSON.fromJson(json,Record.class);assertEquals(1,loaded.chance);assertEquals(r.id,loaded.id);assertEquals(r.nonce,loaded.nonce);assertEquals(r.owner,loaded.owner);assertEquals(.2,loaded.legacyRemainingFraction);assertEquals(512,loaded.maxUses);assertEquals(0,loaded.readyAt);assertTrue(loaded.upgraded);assertEquals(8,loaded.revision);}
 @Test void removedLegacyIdentityRetiresWithoutCorruptingSave(){var c=new ArtifactConfig();var r=generate("multi_pickaxe",c.types.get("multi_pickaxe"),new Random(1));r.type="smelter_pickaxe";r.uses=r.maxUses=2000;var json=com.google.gson.JsonParser.parseString(Store.JSON.toJson(r)).getAsJsonObject();json.addProperty("abilityBalanceVersion",1);Record loaded=Store.JSON.fromJson(json,Record.class);assertTrue(loaded.retired);var d=new Data();d.records.put(loaded.id,loaded);validate(d);assertFalse(active(loaded,1000));}
 @Test void pendingTransactionUsesSameMigration(){var r=generate("vampire_sword",new ArtifactConfig().types.get("vampire_sword"),new Random(1));var tree=com.google.gson.JsonParser.parseString(Store.JSON.toJson(r)).getAsJsonObject();tree.remove("abilityBalanceVersion");tree.addProperty("value",1);Record loaded=Store.JSON.fromJson(tree,Record.class);assertEquals(.25,loaded.value);assertEquals(.5,loaded.upgradedValue);var again=Store.JSON.fromJson(Store.JSON.toJson(loaded),Record.class);assertEquals(loaded.revision,again.revision);}
 @Test void oldDefaultScytheConfigMigratesOnceWithoutChangingDropChances(){var c=new ArtifactConfig();c.chanceByDay.put(1,.1);c.types.get("void_scythe").maxUses=10;var tree=com.google.gson.JsonParser.parseString(Store.JSON.toJson(c)).getAsJsonObject();tree.remove("durabilityBalanceVersion");var loaded=Store.JSON.fromJson(tree,ArtifactConfig.class);assertEquals(1000,loaded.types.get("void_scythe").maxUses);assertEquals(.1,loaded.chance(1));loaded.types.get("void_scythe").maxUses=10;assertEquals(10,Store.JSON.fromJson(Store.JSON.toJson(loaded),ArtifactConfig.class).types.get("void_scythe").maxUses);}
 @Test void oldScytheIdentityMigratesWithoutReplacingNonceOrRevivingRetiredItems(){var r=generate("void_scythe",new ArtifactConfig().types.get("void_scythe"),new Random(1));r.uses=r.maxUses=10;r.retired=true;var tree=com.google.gson.JsonParser.parseString(Store.JSON.toJson(r)).getAsJsonObject();tree.remove("durabilityBalanceVersion");Record loaded=Store.JSON.fromJson(tree,Record.class);assertEquals(1000,loaded.maxUses);assertEquals(r.id,loaded.id);assertEquals(r.nonce,loaded.nonce);assertTrue(loaded.retired);assertEquals(loaded.revision,Store.JSON.fromJson(Store.JSON.toJson(loaded),Record.class).revision);}
}
